CREATE OR REPLACE FUNCTION public.reset_facet_taste() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); BEGIN IF uid IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; PERFORM 1 FROM profiles WHERE id=uid FOR UPDATE; DELETE FROM swipe_receipts WHERE user_id=uid; DELETE FROM user_facet_stats WHERE user_id=uid; DELETE FROM user_taste WHERE user_id=uid; DELETE FROM user_taste_overrides WHERE user_id=uid; DELETE FROM user_taste_portrait WHERE user_id=uid; DELETE FROM swipes WHERE user_id=uid; DELETE FROM tag_weights WHERE user_id=uid; UPDATE taste_events SET active=false WHERE user_id=uid; UPDATE profiles SET swipe_no=0,taste_baseline=NULL,onboarded=false WHERE id=uid; END $$; REVOKE ALL ON FUNCTION public.reset_facet_taste() FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.reset_facet_taste() TO authenticated;
CREATE OR REPLACE FUNCTION public.starting_taste(answers jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE uid uuid:=auth.uid(); BEGIN IF uid IS NULL THEN RAISE EXCEPTION 'Sign in required'; END IF; PERFORM 1 FROM profiles WHERE id=uid FOR UPDATE; IF EXISTS(SELECT 1 FROM profiles WHERE id=uid AND onboarded) THEN RETURN; END IF; INSERT INTO user_facet_stats(user_id,media_type,facet,value,exposures_ew,likes_ew,last_swipe_no) SELECT uid,media,a->>'facet',a->>'value',2,1,p.swipe_no FROM jsonb_array_elements(answers) a CROSS JOIN (VALUES('film'),('book')) m(media) JOIN profiles p ON p.id=uid WHERE a->>'facet' IN ('visual','pace','narrative','tone','era','length','origin') AND length(a->>'value')<80 AND (media='film' OR a->>'facet'<>'visual') ON CONFLICT(user_id,media_type,facet,value) DO NOTHING; UPDATE profiles SET onboarded=true WHERE id=uid; END $$; REVOKE ALL ON FUNCTION public.starting_taste(jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.starting_taste(jsonb) TO authenticated;
CREATE TABLE public.watch_availability(item_id uuid NOT NULL REFERENCES public.items(id) ON DELETE CASCADE,region text NOT NULL DEFAULT 'GE',providers jsonb NOT NULL DEFAULT '{}',link text,fetched_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(item_id,region)); GRANT SELECT ON public.watch_availability TO authenticated; GRANT ALL ON public.watch_availability TO service_role; ALTER TABLE public.watch_availability ENABLE ROW LEVEL SECURITY; CREATE POLICY watch_read ON public.watch_availability FOR SELECT TO authenticated USING(true);